<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { useRouter } from 'vue-router';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { useResponsiveDrawer } from '../province-monitoring';
import { subjectDate as date, subjectError, subjectStatus as statusText } from '../subject-management';
import EnterpriseAccountsPanel from './EnterpriseAccountsPanel.vue';
const props=withDefaults(defineProps<{modelValue:boolean;enterpriseId:string;initialTab?:string;editOnOpen?:boolean}>(),{initialTab:'basic',editOnOpen:false});
const emit=defineEmits<{'update:modelValue':[boolean];changed:[]}>();
const session=useSessionStore(),router=useRouter(),width=useResponsiveDrawer(900);
const visible=computed({get:()=>props.modelValue,set:(v:boolean)=>emit('update:modelValue',v)});
const allowed=(code:string)=>session.user?.permissions.includes(code)??false;
const detail=ref<any>(null),loading=ref(false),error=ref(''),active=ref('basic'),editing=ref(false),saving=ref(false);
const edit=reactive({legalRepresentative:'',contactName:'',contactPhone:'',registeredAddress:''});let original='',generation=0,listGeneration=0;
const related=ref<any>({items:[],total:0}),applications=ref<any>({items:[],total:0}),alerts=ref<any>({items:[],total:0});
const relatedLoading=ref(false),relatedError=ref(''),relatedPage=ref(1),applicationsPage=ref(1),alertsPage=ref(1);
function startEdit(){if(!detail.value)return;for(const key of Object.keys(edit) as Array<keyof typeof edit>)edit[key]=detail.value[key]??'';original=JSON.stringify(edit);active.value='basic';editing.value=true}
async function load(){const request=++generation;listGeneration++;detail.value=null;error.value='';editing.value=false;loading.value=true;relatedError.value='';active.value=props.initialTab;
  try{const row=await api<any>(`/archives/enterprises/${props.enterpriseId}`);if(request!==generation)return;detail.value=row;if(props.editOnOpen)startEdit();else if(['vehicles','records'].includes(active.value))await loadRelated()}
  catch(e){if(request===generation)error.value=subjectError(e)}finally{if(request===generation)loading.value=false}
}
async function loadRelated(){if(!detail.value)return;const request=++listGeneration,enterpriseId=detail.value.id;relatedLoading.value=true;relatedError.value='';
  try{if(active.value==='vehicles'){const result=await api<any>(`/archives/vehicles?enterpriseId=${enterpriseId}&page=${relatedPage.value}&pageSize=10`);if(request===listGeneration)related.value=result}
    else if(active.value==='records'){const [a,b]=await Promise.all([allowed('admission:application:read')?api<any>(`/admission/applications?enterpriseId=${enterpriseId}&page=${applicationsPage.value}&pageSize=10`):Promise.resolve({items:[],total:0}),allowed('safety:alert:read')?api<any>(`/safety/alerts?enterpriseId=${enterpriseId}&page=${alertsPage.value}&pageSize=10`):Promise.resolve({items:[],total:0})]);if(request===listGeneration){applications.value=a;alerts.value=b}}
  }catch(e){if(request===listGeneration)relatedError.value=subjectError(e)}finally{if(request===listGeneration)relatedLoading.value=false}
}
async function save(){saving.value=true;try{await api(`/archives/enterprises/${detail.value.id}`,{method:'PATCH',body:JSON.stringify(edit)});Object.assign(detail.value,edit);editing.value=false;ElMessage.success('企业档案已保存');emit('changed')}catch(e){ElMessage.error(subjectError(e))}finally{saving.value=false}}
async function close(done:()=>void){if(saving.value)return;if(editing.value&&original!==JSON.stringify(edit)){try{await ElMessageBox.confirm('当前修改尚未保存，确定关闭？','关闭企业详情',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}done()}
watch(()=>[props.modelValue,props.enterpriseId] as const,()=>{if(props.modelValue&&props.enterpriseId){relatedPage.value=1;applicationsPage.value=1;alertsPage.value=1;load()}else{generation++;listGeneration++;editing.value=false}},{immediate:true});
watch(active,()=>{if(['vehicles','records'].includes(active.value)&&!loading.value)loadRelated()});
</script>
<template>
<el-drawer v-model="visible" title="企业详情" :size="width" class="subject-drawer" destroy-on-close :before-close="close" :close-on-click-modal="!saving" :close-on-press-escape="!saving">
  <div v-if="error" class="subject-error" role="alert"><strong>企业详情加载失败</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div>
  <el-skeleton v-else-if="loading" :rows="8" animated/>
  <template v-else-if="detail">
    <div class="subject-detail-title"><div><h2>{{detail.name}}</h2><p>{{detail.businessNo}} · {{detail.creditCode}}</p></div><el-tag class="subject-pill" :type="detail.status==='ACTIVE'?'success':'info'">{{statusText(detail.status)}}</el-tag></div>
    <el-tabs v-model="active">
      <el-tab-pane label="基本信息" name="basic">
        <el-form v-if="editing" label-position="top" class="subject-form" :disabled="saving"><el-form-item label="法定代表人"><el-input v-model="edit.legalRepresentative" maxlength="80"/></el-form-item><el-form-item label="企业联系人"><el-input v-model="edit.contactName" maxlength="80"/></el-form-item><el-form-item label="联系电话"><el-input v-model="edit.contactPhone" maxlength="32"/></el-form-item><el-form-item label="注册地址" class="wide"><el-input v-model="edit.registeredAddress" maxlength="300" type="textarea" :rows="3"/></el-form-item></el-form>
        <dl v-else class="subject-detail-grid"><div><dt>企业编号</dt><dd>{{detail.businessNo}}</dd></div><div><dt>统一社会信用代码</dt><dd>{{detail.creditCode}}</dd></div><div><dt>监管机构</dt><dd>{{detail.organization?.name}}</dd></div><div><dt>企业类型</dt><dd>{{detail.type==='OPERATOR'?'运营企业':detail.type}}</dd></div><div><dt>法定代表人</dt><dd>{{detail.legalRepresentative||'—'}}</dd></div><div><dt>企业联系人</dt><dd>{{detail.contactName||'—'}}</dd></div><div><dt>联系电话</dt><dd>{{detail.contactPhone||'—'}}</dd></div><div><dt>登记日期</dt><dd>{{date(detail.createdAt)}}</dd></div><div class="wide"><dt>注册地址</dt><dd>{{detail.registeredAddress||'—'}}</dd></div></dl>
      </el-tab-pane>
      <el-tab-pane :label="`资质证照 ${detail.qualifications.length}`" name="qualifications" :disabled="editing"><el-table :data="detail.qualifications" empty-text="该企业尚未登记资质证照"><el-table-column label="资质类型" prop="qualificationType" min-width="170"/><el-table-column label="证书编号" prop="certificateNo" min-width="150"/><el-table-column label="有效期至" min-width="115"><template #default="{row}">{{date(row.expiresAt)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='VALID'?'success':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane v-if="allowed('archive:vehicle:read')" :label="`关联车辆 ${detail._count.vehicles}`" name="vehicles" :disabled="editing"><div v-if="relatedError" class="subject-inline-error" role="alert">{{relatedError}}<el-button text @click="loadRelated">重试</el-button></div><el-table v-else v-loading="relatedLoading" :data="related.items" empty-text="该企业暂无在册车辆"><el-table-column label="车辆" min-width="200"><template #default="{row}"><div class="subject-identity"><strong>{{row.name}}</strong><span>{{row.unifiedCode}}</span></div></template></el-table-column><el-table-column label="车型" min-width="130"><template #default="{row}">{{row.model.name}}</template></el-table-column><el-table-column label="连接" width="80"><template #default="{row}">{{row.onlineStatus==='ONLINE'?'在线':'离线'}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="visible=false;router.push({path:'/archives/vehicles',query:{vehicleId:row.id}})">详情</el-button></template></el-table-column></el-table><el-pagination v-if="related.total" v-model:current-page="relatedPage" :page-size="10" :total="related.total" layout="total,prev,pager,next" small @current-change="loadRelated"/></el-tab-pane>
      <el-tab-pane v-if="allowed('admission:application:read')||allowed('safety:alert:read')" label="监管记录" name="records" :disabled="editing"><el-button v-if="allowed('analytics:profile:read')" style="margin:8px 0 16px" @click="visible=false;router.push({path:'/archives/enterprises',query:{view:'profile',enterpriseId:detail.id}})">查看企业安全画像 →</el-button><div v-if="relatedError" class="subject-inline-error" role="alert">{{relatedError}}<el-button text @click="loadRelated">重试</el-button></div><div v-else v-loading="relatedLoading"><template v-if="allowed('admission:application:read')"><h3 class="subject-detail-section">准入审批记录</h3><el-table :data="applications.items" empty-text="暂无准入审批记录"><el-table-column label="申请" min-width="190"><template #default="{row}"><div class="subject-identity"><strong>{{row.title||row.businessNo}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column label="类型" min-width="110"><template #default="{row}">{{({ENTERPRISE_ONBOARDING:'企业准入',ROAD_TEST:'道路测试',LICENSE_RENEWAL:'许可续期'} as any)[row.applicationType]||row.applicationType}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}">{{statusText(row.status)}}</template></el-table-column></el-table><el-pagination v-if="applications.total" v-model:current-page="applicationsPage" :page-size="10" :total="applications.total" layout="total,prev,pager,next" small @current-change="loadRelated"/></template><template v-if="allowed('safety:alert:read')"><h3 class="subject-detail-section">安全告警记录</h3><el-table :data="alerts.items" empty-text="暂无安全告警记录"><el-table-column prop="title" label="告警" min-width="190"/><el-table-column label="发生日期" width="115"><template #default="{row}">{{date(row.occurredAt)}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}">{{statusText(row.status)}}</template></el-table-column></el-table><el-pagination v-if="alerts.total" v-model:current-page="alertsPage" :page-size="10" :total="alerts.total" layout="total,prev,pager,next" small @current-change="loadRelated"/></template></div></el-tab-pane>
      <el-tab-pane v-if="allowed('system:user:read')" label="企业账号" name="accounts" :disabled="editing"><EnterpriseAccountsPanel v-if="active==='accounts'" :enterprise-id="detail.id" :organization-id="detail.organizationId" @changed="emit('changed')"/></el-tab-pane>
    </el-tabs>
  </template>
  <template #footer><template v-if="editing"><el-button :disabled="saving" @click="editing=false">取消编辑</el-button><el-button type="primary" :loading="saving" @click="save">保存档案</el-button></template><template v-else><el-button @click="visible=false">关闭</el-button><el-button v-if="detail&&allowed('archive:enterprise-archive:write')" type="primary" @click="startEdit">编辑档案</el-button></template></template>
</el-drawer>
</template>
